mapper.select:
SELECT po.po_id AS poId, po.po_no AS poNo, br.name AS branchName, DATE_FORMAT(po.request_date, "%Y-%m-%d %H:%i:%s") AS requestedAt,
COUNT(pod.po_detail_id) AS totalItemCnt, COALESCE(SUM(pod.requested_qty), 0) AS totalAmounts,
po.status AS status
FROM place_order AS po JOIN branch br ON po.branch_code = br.branch_code LEFT JOIN place_order_detail pod ON po.po_id = pod.po_id
AND br.name = #{branchName}
AND DATE(po.request_date) >= #{startDate}
AND DATE(po.request_date) <= #{endDate}
GROUP BY po.po_id, po.po_no, br.name, po.request_date, po.status
ORDER BY po.request_date DESC

SELECT po.po_id AS poId, po.po_no AS poNo, b.name AS branchName, DATE_FORMAT(po.request_date, '%Y-%m-%d %H:%i:%s') AS requestedAt, po.status AS status, po.reject_reason AS rejectReason, po.total_material_cnt AS totalItemCnt, po.total_amount AS totalAmounts
FROM place_order po JOIN branch b ON po.branch_code = b.branch_code
WHERE po.po_id = #{poId}
